BEGIN TRANSACTION READ ONLY;
WITH checks AS (SELECT (SELECT count(*) FROM public.tenant_features WHERE cliente_id='69095bd5-fee5-4237-a1a4-186dd88310ff'::uuid AND feature_key='WORKDAY_PERSIST_ACTIVE' AND mode='PERSIST_ACTIVE' AND enabled AND canary_registro_id IS NULL AND canary_empleado_id IS NULL AND canary_schedule_id IS NULL AND canary_workday_date IS NULL)=1 AS pilot_enabled_exactly_once,(SELECT count(*) FROM public.tenant_features WHERE feature_key='WORKDAY_PERSIST_ACTIVE' AND enabled)=1 AS no_global_or_other_tenant_authorization,(SELECT count(*) FROM public.tenant_features WHERE feature_key='WORKDAY_PERSIST_CANARY')=0 AS temporary_canary_remains_closed,to_regclass('public.attendance_persist_outbox') IS NOT NULL AS outbox_exists,EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid='public.upsert_workday_record(uuid,uuid,date,uuid,text,timestamptz,timestamptz,integer,integer,integer,integer,integer,text,text,integer,uuid)'::regprocedure AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND has_function_privilege('service_role',p.oid,'EXECUTE')) AS rpc_service_role_only), e AS (SELECT entry.key,entry.value FROM checks CROSS JOIN LATERAL jsonb_each_text(to_jsonb(checks)) entry(key,value)) SELECT jsonb_build_object('phase','94_productive_persist_pilot_authorization_postcheck','read_only',current_setting('transaction_read_only'),'checks',(SELECT to_jsonb(checks) FROM checks),'failed_checks',COALESCE((SELECT jsonb_agg(key ORDER BY key) FILTER(WHERE value<>'true') FROM e),'[]'::jsonb)) FROM checks;
ROLLBACK;
